import{_ as e,c as o,o as a,a4 as c}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q16：异步编程的演进：回调、Promise、async/await","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q16.md","filePath":"frontend/q16.md","lastUpdated":null}'),t={name:"frontend/q16.md"},i=c('<h1 id="q16-异步编程的演进-回调、promise、async-await" tabindex="-1">Q16：异步编程的演进：回调、Promise、async/await <a class="header-anchor" href="#q16-异步编程的演进-回调、promise、async-await" aria-label="Permalink to &quot;Q16：异步编程的演进：回调、Promise、async/await&quot;">​</a></h1><p><strong>回调函数</strong><br> 早期处理异步，但容易产生“回调地狱”，代码难以维护，错误处理复杂。</p><p><strong>Promise</strong><br> 解决了回调地狱和信任问题。</p><ul><li>三种状态：<code>pending</code>（待定）、<code>fulfilled</code>（已兑现）、<code>rejected</code>（已拒绝），状态一旦变化就不可逆。</li><li>实例方法：<code>.then()</code> 返回新 Promise 实现链式调用；<code>.catch()</code> 捕获错误；<code>.finally()</code> 执行收尾。</li><li>静态方法：<code>Promise.all()</code>（全部成功才成功）、<code>Promise.race()</code>（一个完成就决定）、<code>Promise.allSettled()</code>（所有都落定）、<code>Promise.any()</code>（任一成功）。</li><li>缺点：依旧有链式调用，不够优雅，且错误需要用 <code>.catch</code> 捕获。</li></ul><p><strong>async/await</strong><br> ES7 引入，是 <strong>Generator + Promise 的语法糖</strong>。用同步的方式写异步代码。</p><ul><li><code>async</code> 函数返回 Promise。</li><li><code>await</code> 会暂停函数执行，等待 Promise 结果。</li><li>错误用 <code>try/catch</code> 包裹，更加直观。</li><li>注意 <code>await</code> 循环中的并行与串行处理。</li></ul>',6),r=[i];function d(s,n,l,_,m,p){return a(),o("div",null,r)}const h=e(t,[["render",d]]);export{f as __pageData,h as default};
